<?php
namespace App\Support;
use App\Models\{User,Apprentice,ProgrammeOutcome,Programme,LearningTask,CohortForecast,CohortSnapshot as Snapshot};
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
class CohortInsights {
 public static function validDate($date):bool {return is_string($date)&&preg_match('/^\d{4}-\d{2}-\d{2}$/D',$date)&&checkdate((int)substr($date,5,2),(int)substr($date,8,2),(int)substr($date,0,4));}
 public static function outcome(Apprentice $a,array $c):array {$status=$c['status']??'Unknown';$ok=in_array($status,['Active','Break in learning','Completed','Withdrawn','Transferred'],true)&&filled($c['sourceRef']??null);$ended=in_array($status,['Completed','Withdrawn','Transferred'],true);if($ended){$ok=$ok&&self::validDate($c['endDate']??null)&&$a->start_date&&$c['endDate']>=$a->start_date->toDateString()&&$c['endDate']<=today()->toDateString();}elseif(filled($c['endDate']??null)){$ok=false;}$achievement='Unknown';if($ok&&$status==='Completed'){if(($c['achievement']??null)==='Achieved'&&self::validDate($c['achievementDate']??null)&&$c['achievementDate']>=$c['endDate']&&$c['achievementDate']<=today()->toDateString()){$achievement='Achieved';}elseif(($c['achievement']??null)==='Not achieved'&&!filled($c['achievementDate']??null)){$achievement='Not achieved';}elseif(($c['achievement']??null)==='Awaiting result'){$achievement='Awaiting result';}}
 return ['status'=>$ok?$status:'Unknown','achievement'=>$achievement,'needs_check'=>!$ok||$status==='Completed'&&$achievement==='Unknown','end_date'=>$ok&&$ended?$c['endDate']:null];}
 public static function stage(?array $plan):string {if(!$plan){return 'Approved plan missing';}$blocks=$plan['blocks']??[];$matches=[];$starts=[];$ends=[];foreach($blocks as$b){if(!in_array($b['number']??null,range(1,12),true)||!self::validDate($b['start']??null)||!self::validDate($b['end']??null)||$b['end']<$b['start']){return 'Plan dates need checking';}$starts[]=$b['start'];$ends[]=$b['end'];if($b['start']<=today()->toDateString()&&$b['end']>=today()->toDateString()){$matches[]=$b['number'];}}if(count($matches)===1){return 'Block '.$matches[0];}if(count($matches)>1){return 'Overlapping plan blocks';}if(!$starts){return 'Plan dates need checking';}return today()->toDateString()<min($starts)?'Before approved plan':(today()->toDateString()>max($ends)?'Beyond approved plan':'Between plan blocks');}
 public static function emptyCounts():array {return ['cohort'=>0,'active'=>0,'break'=>0,'completed'=>0,'withdrawn'=>0,'transferred'=>0,'unknown'=>0,'achieved'=>0,'not_achieved'=>0,'awaiting_result'=>0,'result_unknown'=>0,'past_recorded_end'=>0,'planned_end_unknown'=>0,'source_checks'=>0,'current_forecasts'=>0,'forecasts_needing_review'=>0,'forecast_missing'=>0,'assigned_tasks'=>0,'approved_tasks'=>0,'source_pending_tasks'=>0];}
 public static function report(User $u,string $from,string $to,?int $programme=null,?int $tutor=null):array {abort_unless(LearningAccess::manager($u)&&!AccountLifecycle::blocked($u),403);validator(['from'=>$from,'to'=>$to],['from'=>'required|date_format:Y-m-d','to'=>'required|date_format:Y-m-d|after_or_equal:from|before_or_equal:today'])->validate();abort_if(\Carbon\Carbon::parse($from)->diffInDays(\Carbon\Carbon::parse($to))>3660,422,'Choose a cohort start interval of at most ten years.');$base=Apprentice::query()->when($programme,fn($q)=>$q->where('programme_id',$programme))->when($tutor,fn($q)=>$q->where('tutor_id',$tutor));$missingStart=(clone$base)->whereRaw('DATE(start_date) IS NULL')->count();$people=(clone$base)->whereDate('start_date','>=',$from)->whereDate('start_date','<=',$to)->orderBy('id')->limit(1001)->get();abort_if($people->count()>1000,422,'Narrow the cohort; more than1000 records.');$tot=self::emptyCounts();$groups=[];$details=[];$bindings=[];
 foreach($people as$a){$c=ProgrammeOutcome::where('apprentice_id',$a->id)->first()?->context??[];$o=self::outcome($a,$c);$source=CohortForecasts::source($a);$stage=self::stage($source['approved_plan']);$p=$a->programmeRecord()->first();$key=(string)($p?->id??'unknown');$groups[$key]??=['programme'=>$p?->name??'Programme unknown','standard'=>$p?->standard_code,'version'=>$p?->version,'level'=>$p?->level,'counts'=>self::emptyCounts(),'stages'=>[]];$count=self::emptyCounts();$count['cohort']=1;$statusKey=match($o['status']){'Active'=>'active','Break in learning'=>'break','Completed'=>'completed','Withdrawn'=>'withdrawn','Transferred'=>'transferred',default=>'unknown'};$count[$statusKey]++;$count['source_checks']+=(int)$o['needs_check'];if($o['status']==='Completed'){$count[match($o['achievement']){'Achieved'=>'achieved','Not achieved'=>'not_achieved','Awaiting result'=>'awaiting_result',default=>'result_unknown'}]++;}
  $knownEnd=$a->planned_end_date&&$a->start_date&&$a->planned_end_date->gte($a->start_date);if(!$knownEnd){$count['planned_end_unknown']++;}elseif($o['status']==='Active'&&$a->planned_end_date->lt(today())){$count['past_recorded_end']++;}
  $tasks=LearningTask::where('apprentice_id',$a->id)->get(['id','status','template']);$count['assigned_tasks']=$tasks->count();$count['source_pending_tasks']=$tasks->filter(fn($t)=>($t->template['kind']??'source-pending')==='source-pending')->count();$count['approved_tasks']=$tasks->filter(fn($t)=>$t->status==='Approved'&&($t->template['kind']??'source-pending')!=='source-pending')->count();$f=CohortForecast::find($a->id);$current=$f&&CohortForecasts::current($f,$source);$count[$f?($current?'current_forecasts':'forecasts_needing_review'):'forecast_missing']++;$groups[$key]['stages'][$stage]=($groups[$key]['stages'][$stage]??0)+1;foreach($count as$k=>$n){$tot[$k]+=$n;$groups[$key]['counts'][$k]+=$n;}$details[]=['apprentice'=>$a,'outcome'=>$o,'stage'=>$stage,'forecast'=>$current?$f->details:null,'forecast_state'=>$current?'Current checked staff estimate':($f?'Estimate needs review':'No recorded estimate'),'recorded_end'=>$knownEnd?$a->planned_end_date->toDateString():null];$bindings[]=['id'=>$a->id,'source_hash'=>$source['hash'],'forecast_hash'=>$f?ReviewedImports::hash($f->getAttributes()):null];
 }
 $rate=function(array $c):?float {return $c['completed']&&$c['awaiting_result']===0&&$c['result_unknown']===0?100*$c['achieved']/$c['completed']:null;};foreach($groups as&$g){$g['confirmed_completion_result_percent']=$rate($g['counts']);ksort($g['stages']);}unset($g);$safe=['from'=>$from,'to'=>$to,'programme_filter'=>$programme,'current_tutor_filter'=>$tutor,'captured_at'=>now()->toIso8601String(),'cohort_definition'=>'Recorded apprentice start dates within inclusive interval; current recorded context at capture','missing_start_outside_cohort'=>$missingStart,'counts'=>$tot,'confirmed_completion_result_percent'=>$rate($tot),'groups'=>array_values($groups),'official_qar'=>false,'historical_staff_attribution'=>false];$stable=$safe;unset($stable['captured_at']);return ['aggregate'=>$safe,'details'=>$details,'source_hash'=>ReviewedImports::hash(['report'=>$stable,'bindings'=>$bindings]),'filters'=>compact('from','to','programme','tutor')];}
 public static function snapshot(User $actor,int $auth,string $from,string $to,?int $programme,?int $tutor,string $expected):Snapshot {return DB::transaction(function()use($actor,$auth,$from,$to,$programme,$tutor,$expected):Snapshot {$u=PortalOperations::actor($actor,$auth,true);$report=self::report($u,$from,$to,$programme,$tutor);if($expected!==$report['source_hash']){CentrePlanning::fail('Cohort source changed since preview; review the current report.');}$body=['format'=>'gta-cohort-snapshot43','source_hash'=>$expected,'report'=>$report['aggregate']];$s=Snapshot::create(['id'=>(string)Str::uuid(),'created_by'=>$u->id,'body'=>$body,'body_hash'=>ReviewedImports::hash($body)]);PortalOperations::event($u,'cohort',$s->id,'cohort_snapshot_saved',['body_hash'=>$s->body_hash,'aggregate_only'=>true]);return $s;},3);}
 public static function readSnapshot(Snapshot $s):array {try{$body=$s->body;if(ReviewedImports::hash($body)!==$s->body_hash||$body['format']!=='gta-cohort-snapshot43'){throw new \RuntimeException();}return $body;}catch(\Throwable){CentrePlanning::fail('Snapshot integrity needs recovery; no live data is substituted.');}}
 public static function compare(Snapshot $a,Snapshot $b):array {$x=self::readSnapshot($a)['report'];$y=self::readSnapshot($b)['report'];foreach(['from','to','programme_filter','current_tutor_filter']as$k){if($x[$k]!==$y[$k]){CentrePlanning::fail('Compare snapshots only with the same cohort/filter definition.');}}if(\Carbon\Carbon::parse($x['captured_at'])->gt(\Carbon\Carbon::parse($y['captured_at']))){CentrePlanning::fail('Choose the earlier captured snapshot first.');}$changes=[];foreach($x['counts']as$k=>$n){$changes[$k]=$y['counts'][$k]-$n;}return ['earlier_capture'=>$x['captured_at'],'later_capture'=>$y['captured_at'],'changes'=>$changes,'interpretation'=>'Difference between captured current records for the same start cohort; not causal tutor effectiveness or a reconstructed official return'];}
}
